',children:'/// The result names its own destination, so the subscriber takes no name for its reply.\n#[derive(Debug, PartialEq, Deserialize, Serialize, JsonSchema)]\n#[schemars(crate = "ruststream::schemars")]\nstruct Done {\n    id: u64,\n}\n\n// `#[outgoing(name = "results")]` by hand.\nimpl OutgoingDestination for Done {\n    type Form = FixedName;\n    const DESTINATION: &\'static str = "results";\n}\n\nimpl MessageHeaders for Done {\n    type Contract = NoHeaders;\n}\n\nstruct Work;\n\nimpl Handle<Job, Done> for Work {\n    fn handle(\n        &self,\n        job: &Job,\n        _outs: &(),\n        _ctx: &mut Context<\'_>,\n    ) -> impl Future<Output = Result<Done, HandlerOutcome>> {\n        tracing::info!(job.id, "working");\n        ready(Ok(Done { id: job.id }))\n    }\n}\n'})}),(0,s.jsx)(t.pre,{children:(0,s.jsx)(t.code,{className:"language-rust",metastring:'title="https://github.com/powersemmi/ruststream-zeromq/blob/main/crates/ruststream-zeromq/examples/manual/zmq_publishing_replies.rs"',children:'fn app() -> impl App {\n    // The sink binds its own endpoint; this worker dials it to deliver the results.\n    let results = ZmqQueue::new(ZmqEndpoint::connect("tcp://sink:5556")).bindable();\n    let to_results = results.bind(Publish);\n    RustStream::new(AppInfo::new("worker", "0.1.0"))\n        .with_broker(\n            ZmqQueue::new(ZmqEndpoint::bind("tcp://0.0.0.0:5555")),\n            |b| {\n                b.include(subscriber("jobs", Work).reply().build())\n                    .out_reply(to_results);\n            },\n        )\n        .register_broker(results)\n}\n'})})]})]})]})}function p(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(h,{...e})}):h(e)}},7250(e,t,n){n.d(t,{A:()=>o});var r=n(4848);n(6540);var s=n(4164),i=n(7663);function a({children:e,className:t,hidden:n}){return(0,r.jsx)("div",{role:"tabpanel",className:(0,s.A)("tabItem_Ymn6",t),hidden:n,children:e})}function o({children:e,cla